(() => {
  'use strict';
  const STORAGE='ropad.fee-sharing.pending.v1',ADDRESS=/^[1-9A-HJ-NP-Za-km-z]{32,44}$/,UUID=/^[a-f0-9-]{36}$/;
  let active=null,epoch=0;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const bytes64=value=>{let text='';for(const byte of value)text+=String.fromCharCode(byte);return btoa(text);};
  const decode64=value=>{if(typeof value!=='string'||value.length>1800||!/^[A-Za-z0-9+/]+={0,2}$/.test(value))throw Error('The fee transaction encoding is invalid');const bytes=Uint8Array.from(atob(value),c=>c.charCodeAt(0));if(bytes.length>1232||bytes64(bytes)!==value)throw Error('The fee transaction encoding is invalid');return bytes;};
  const lamports=value=>{if(!/^-?\d+$/.test(String(value)))return 'Unavailable';const amount=BigInt(value),n=amount<0n?-amount:amount,fraction=(n%1000000000n).toString().padStart(9,'0').replace(/0+$/,'');return (amount<0n?'-':'')+(n/1000000000n)+(fraction?'.'+fraction:'')+' SOL';};
  function configValid(c){const splits=c?.splitBps;return c?.status==='configured'&&c.cluster==='mainnet-beta'&&ADDRESS.test(c.platformMint||'')&&ADDRESS.test(c.platformTreasury||'')&&ADDRESS.test(c.computeTreasury||'')&&c.platformTreasury!==c.computeTreasury&&!!splits&&['compute,platform','compute,creator,platform'].includes(Object.keys(splits).sort().join(','))&&Object.values(splits).every(bps=>Number.isInteger(bps)&&bps>0)&&Object.values(splits).reduce((sum,bps)=>sum+bps,0)===10000;}
  function sharesMatch(shares,c,creator){const hasCreator=!!c?.splitBps?.creator,count=hasCreator?3:2;if(hasCreator&&(!ADDRESS.test(creator||'')||creator===c.platformTreasury||creator===c.computeTreasury))return false;return configValid(c)&&Array.isArray(shares)&&shares.length===count&&new Set(shares.map(s=>s.address)).size===count&&shares.every(s=>s.shareBps===(s.address===c.platformTreasury?c.splitBps.platform:s.address===c.computeTreasury?c.splitBps.compute:hasCreator&&s.address===creator?c.splitBps.creator:-1));}
  function quoteValid(q,s){return q?.status==='prepared'&&UUID.test(q.intentId||'')&&q.owner===s.owner&&q.projectId===s.projectId&&q.mint===s.mint&&q.action===s.action&&q.cluster==='mainnet-beta'&&q.realFunds===true&&q.simulation==='passed'&&q.transactionVersion==='v0'&&Number.isFinite(q.expiresAt)&&q.expiresAt>Date.now()&&/^[1-9]\d*$/.test(String(q.estimatedNetworkFeeLamports))&&BigInt(q.estimatedNetworkFeeLamports)<=250000n&&q.platformMint===s.config.platformMint&&q.permanentShares===(q.action==='configure')&&(!s.config.splitBps.creator||q.creatorWallet===s.owner)&&sharesMatch(q.shares,s.config,s.owner)&&typeof q.transactionBase64==='string';}
  function recordMatches(r,s,intentId){return r&&r.intentId===intentId&&r.owner===s.owner&&r.projectId===s.projectId&&r.mint===s.mint&&r.cluster==='mainnet-beta'&&['prepared','pending','confirmed','reverted','expired'].includes(r.status);}
  const current=s=>active===s&&s.epoch===epoch&&s.root?.isConnected;
  const storageKey=s=>s.buildId+':'+s.owner;
  function saved(s){try{const row=JSON.parse(localStorage.getItem(STORAGE)||'{}')[storageKey(s)];return row&&UUID.test(row.intentId||'')&&row.owner===s.owner&&row.mint===s.mint&&row.projectId===s.projectId?row:null;}catch{return null;}}
  function remember(s,row){let all;try{all=JSON.parse(localStorage.getItem(STORAGE)||'{}');if(!all||Array.isArray(all)||typeof all!=='object')throw Error();if(row)all[storageKey(s)]=row;else delete all[storageKey(s)];localStorage.setItem(STORAGE,JSON.stringify(all));}catch{throw Error('Browser recovery storage is unavailable No transaction was submitted');}}
  async function api(url,body){const headers={};if(body!==undefined){const r=await fetch('/api/status',{credentials:'same-origin',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Reload Ropad before continuing');const p=await r.json();if(typeof p.csrf!=='string')throw Error('Reload Ropad before continuing');headers['X-Parallax-Token']=p.csrf;headers['Content-Type']='application/json';}const r=await fetch(url,{method:body===undefined?'GET':'POST',headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(60000)});let p;try{p=await r.json();}catch{throw Error('The fee service returned an unreadable response');}if(!r.ok)throw Error(typeof p.error==='string'?p.error:'Fee request could not complete');return p;}
  async function check(s){if(!current(s))throw Error('This fee review is closed');const wallet=await window.RopadSolana.check(s.owner);if(!current(s)||wallet.address!==s.owner)throw Error('Wallet changed Open a new fee review');return wallet;}
  const shareRows=s=>`<dl class="r-fees-shares">${s.config.splitBps.creator?`<div><dt>Game creator · ${esc(s.config.splitBps.creator/100)}%</dt><dd><code>${esc(s.owner)}</code></dd></div>`:''}<div><dt>Platform treasury · ${esc(s.config.splitBps.platform/100)}%</dt><dd><code>${esc(s.config.platformTreasury)}</code></dd></div><div><dt>Compute treasury · ${esc(s.config.splitBps.compute/100)}%</dt><dd><code>${esc(s.config.computeTreasury)}</code></dd></div><div><dt>Platform token</dt><dd><code>${esc(s.config.platformMint)}</code></dd></div></dl>`;
  function render(s){
    if(!current(s))return;const q=s.quote,configured=configValid(s.config),pending=s.pending,verified=s.inspection?.onChainConfigurationVerified===true&&s.inspection.adminRevoked===true&&sharesMatch(s.inspection.shares,s.config,s.owner);
    s.root.innerHTML=`<div class="r-fees-panel"><span class="r-solana-network">CREATOR FEES / SOLANA MAINNET</span><h2>${q?'Review '+(q.action==='configure'?'permanent fee sharing':'fee distribution'):'Creator fee sharing'}</h2><p>${esc(s.gameName||'Your game coin')}</p>${configured?shareRows(s):`<p>${esc(s.config?.reason||'An operator must configure the platform token, two treasury addresses and exact fee split')}</p>`}<p class="r-fees-disclosure"><strong>${s.config?.splitBps?.creator?'Creator fees are shared between the game creator, platform and compute treasuries at the displayed split':'All creator fees go to the platform and compute treasuries at the displayed split'}</strong> Configuring this split is permanent and revokes future share updates ${s.config?.splitBps?.creator?'The creator recipient must match the verified launching wallet':'The signing creator keeps no share unless one of these treasuries is theirs'} This does not buy the platform token or automatically purchase OpenRouter credits</p>`+
      (pending?`<div class="r-trade-pending"><strong>Fee transaction awaiting confirmation</strong><p>Recover this exact transaction before preparing another</p><button class="button" data-fees-status ${s.busy?'disabled':''}>Check saved transaction</button>${pending.signature&&/^[1-9A-HJ-NP-Za-km-z]{64,90}$/.test(pending.signature)?`<a href="https://solscan.io/tx/${esc(pending.signature)}" target="_blank" rel="noopener">Inspect transaction ↗</a>`:''}</div>`:q?`<dl class="r-fees-quote"><div><dt>Coin mint</dt><dd><code>${esc(q.mint)}</code></dd></div><div><dt>Signing wallet</dt><dd><code>${esc(q.owner)}</code></dd></div><div><dt>Network fee estimate</dt><dd>${lamports(q.estimatedNetworkFeeLamports)}</dd></div>${q.estimatedWalletSolChangeLamports!==undefined?`<div><dt>Simulated wallet SOL change</dt><dd>${lamports(q.estimatedWalletSolChangeLamports)}</dd></div>`:''}</dl><p>${q.rentMayApply?'Creating fee accounts also requires rent The network fee shown is not the total SOL cost':'Wallet simulation and network fees can change before confirmation'}</p><p>${q.action==='configure'?'Permanently assigns 100% of creator fees to the exact recipients above':'Sends accrued creator fees to those recipients Amounts are verified from the finalized receipt'}</p><label class="r-fees-ack"><input type="checkbox" data-fees-ack ${s.ack?'checked':''} ${s.busy?'disabled':''}>${q.action==='configure'?'I understand this permanent assignment of all creator fees':'I approve distributing accrued fees to these exact recipients'}</label><div class="r-solana-actions"><button class="button primary" data-fees-sign ${!s.ack||s.busy?'disabled':''}>${q.action==='configure'?'Approve permanent split in wallet':'Approve distribution in wallet'} ↗</button><button class="button" data-fees-back ${s.busy?'disabled':''}>Back</button></div>`:`<p>${verified?'The exact permanent split is verified on chain':'An on-chain fee configuration has not been verified for this coin'}</p><div class="r-solana-actions"><button class="button primary" data-fees-configure ${!configured||verified||s.busy?'disabled':''}>Review permanent fee split</button><button class="button" data-fees-distribute ${!configured||!verified||s.busy?'disabled':''}>Review accrued fee distribution</button><button class="button" data-fees-inspect ${!configured||s.busy?'disabled':''}>Check on-chain configuration</button></div>`)+`<p class="r-trade-feedback ${s.error?'is-error':''}" role="status">${esc(s.error||s.message||'Preparing a review does not sign or send a transaction')}</p></div>`;
    const bind=(selector,fn)=>s.root.querySelector(selector)?.addEventListener('click',()=>run(s,fn));
    bind('[data-fees-configure]',()=>prepare(s,'configure'));bind('[data-fees-distribute]',()=>prepare(s,'distribute'));bind('[data-fees-inspect]',()=>inspect(s));bind('[data-fees-status]',()=>status(s));bind('[data-fees-sign]',()=>sign(s));
    s.root.querySelector('[data-fees-ack]')?.addEventListener('change',event=>{s.ack=event.target.checked===true;const button=s.root.querySelector('[data-fees-sign]');if(button)button.disabled=!s.ack||s.busy;});
    s.root.querySelector('[data-fees-back]')?.addEventListener('click',()=>{if(s.busy)return;s.quote=null;s.ack=false;render(s);});
  }
  async function run(s,fn){if(!current(s)||s.busy)return;s.busy=true;s.error='';render(s);try{await fn();}catch(e){if(current(s))s.error=e.code===4001?'Wallet request cancelled':e.message||'Fee action did not complete';}finally{if(current(s)){s.busy=false;render(s);}}}
  async function inspect(s){await check(s);const result=await api('/api/solana/fees/inspect',{buildId:s.buildId});await check(s);if(result.projectId!==s.projectId||result.mint!==s.mint)throw Error('The fee inspection belongs to a different game');s.inspection=result;s.message=result.onChainConfigurationVerified?'On-chain fee configuration checked':'This coin does not yet have the configured permanent split';}
  async function prepare(s,action){await check(s);if(s.pending)throw Error('Check the pending fee transaction first');if(!configValid(s.config))throw Error('Operator fee configuration is unavailable');s.action=action;s.quote=null;s.ack=false;const q=await api('/api/solana/fees/prepare',{buildId:s.buildId,action});await check(s);if(!quoteValid(q,s))throw Error('The complete fee preview does not match the reviewed recipients, coin and wallet');decode64(q.transactionBase64);s.quote=JSON.parse(JSON.stringify(q));s.message='Review the exact recipient addresses and fees before approving in your wallet';}
  async function sign(s){
    const q=s.quote;if(!s.ack)throw Error('Acknowledge the exact fee assignment before wallet approval');if(!quoteValid(q,s))throw Error('The fee review expired or changed Request a fresh quote');if(s.pending)throw Error('Check the pending fee transaction first');
    await window.RopadSolana.authenticate();const wallet=await check(s);if(typeof wallet.provider?.signTransaction!=='function'||!window.solanaWeb3?.VersionedTransaction)throw Error('A desktop Solana wallet is required');
    const tx=window.solanaWeb3.VersionedTransaction.deserialize(decode64(q.transactionBase64)),message=tx.message;
    if(message.version!==0||message.header.numRequiredSignatures!==1||message.addressTableLookups.length||message.staticAccountKeys[0].toString()!==s.owner)throw Error('The fee transaction signer does not match this review');
    const reviewedMessage=bytes64(message.serialize()),signed=await wallet.provider.signTransaction(tx);await check(s);if(!quoteValid(q,s)||bytes64(signed.message.serialize())!==reviewedMessage)throw Error('The signed fee transaction changed or expired No transaction was submitted');
    const recovery={intentId:q.intentId,owner:s.owner,projectId:s.projectId,mint:s.mint,cluster:'mainnet-beta',action:q.action,createdAt:Date.now()};remember(s,recovery);s.pending=recovery;s.quote=null;s.ack=false;render(s);
    let result;try{result=await api('/api/solana/fees/submit',{intentId:q.intentId,signedTransactionBase64:bytes64(signed.serialize())});}catch{throw Error('Submission outcome is unknown Check the saved fee transaction before approving anything else');}await check(s);
    if(!recordMatches(result,s,q.intentId))throw Error('The fee submission response does not match this review Check its saved status');if(result.signature){s.pending.signature=result.signature;remember(s,s.pending);}s.message='Signed fee transaction saved Check for finalized confirmation';
  }
  async function status(s){const pending=s.pending;if(!pending)return;await window.RopadSolana.authenticate();await check(s);const result=await api('/api/solana/fees/status',{intentId:pending.intentId});await check(s);if(!recordMatches(result,s,pending.intentId))throw Error('The fee status belongs to a different transaction');
    if(result.status==='confirmed'){if(result.finalized!==true||result.onChainConfigurationVerified!==true)throw Error('Finalized on-chain fee verification is not yet available');remember(s,null);s.pending=null;s.message='Fee transaction finalized on Solana No OpenRouter credit or platform-token purchase is inferred';await inspect(s);}
    else if(['reverted','expired'].includes(result.status)){remember(s,null);s.pending=null;s.quote=null;s.message=result.status==='reverted'?'The fee transaction failed on chain Network fees may still have been charged':'The signed transaction expired without a confirmed change';}
    else{s.pending={...pending,...(result.signature?{signature:result.signature}:{})};remember(s,s.pending);s.message=result.status==='prepared'?'The server has not recorded submission Keep this review for recovery before approving another transaction':'Still awaiting finalized confirmation';}
  }
  async function open(buildId){
    const ticket=++epoch;active=null;window.openInfo('ROPAD / CREATOR FEES','<div data-ropad-fees-root><h2>Loading creator fees</h2><p>Checking the launching wallet and verified game token</p></div>');const root=document.getElementById('info-body')?.querySelector('[data-ropad-fees-root]');const s={epoch:ticket,root,buildId,busy:true,error:'',message:'',quote:null,ack:false,pending:null,config:null};active=s;
    try{if(!UUID.test(buildId||''))throw Error('Choose a saved game coin');const wallet=window.RopadSolana?.get();if(!wallet)throw Error('Connect the launching Phantom or Solflare wallet first');s.owner=wallet.address;await window.RopadSolana.authenticate();await check(s);
      const [{build},config,list]=await Promise.all([api('/api/builds/'+encodeURIComponent(buildId)),api('/api/solana/fees/config'),api('/api/solana/fees/list',{buildId})]);await check(s);
      if(build?.id!==buildId||build.canManage!==true||build.token?.chain!=='solana'||build.token.cluster!=='mainnet-beta'||build.token.verified!==true||!ADDRESS.test(build.token.address||''))throw Error('Only the creator of a verified Solana mainnet game coin can manage its fees');
      s.mint=build.token.address;s.projectId=build.lineage?.projectId||buildId;s.gameName=build.gameName;s.config=config;
      const recorded=(Array.isArray(list.data)?list.data:[]).filter(r=>r.status==='pending'&&r.owner===s.owner&&r.mint===s.mint&&r.projectId===s.projectId);if(recorded.length>1)throw Error('Multiple fee transactions need operator recovery');s.pending=recorded[0]||saved(s);if(s.pending)remember(s,{intentId:s.pending.intentId,owner:s.owner,projectId:s.projectId,mint:s.mint,cluster:'mainnet-beta',signature:s.pending.signature});
      if(!s.pending&&configValid(config))try{await inspect(s);}catch(e){s.message=e.message;}
    }catch(e){if(current(s))s.error=e.message||'Creator fees could not be loaded';}finally{if(current(s)){s.busy=false;render(s);}}
  }
  function invalidate(){epoch++;const s=active;active=null;if(s?.root?.isConnected)s.root.innerHTML='<h2>Fee review closed</h2><p>Your wallet or page changed Open a new review with the coin creator wallet</p>';}
  window.addEventListener('ropad-solana-wallet-change',invalidate);window.addEventListener('hashchange',invalidate);document.getElementById('info-dialog')?.addEventListener('close',()=>{epoch++;active=null;});
  window.RopadFeeSharing={open};
})();
